import type { Metadata } from "next";
import { site } from "@/content/site";

/** Generated by `src/app/opengraph-image.tsx`; used when a page has no image of its own. */
const DEFAULT_IMAGE = "/opengraph-image";

type PageMeta = {
  title: string;
  description: string;
  /** path from the site root, e.g. `/services/web-development` */
  path: string;
  /** share image under /public; falls back to the generated brand card */
  image?: string;
  type?: "website" | "article";
  /** ISO date, articles only */
  publishedTime?: string;
};

/**
 * Per-page metadata with canonical, Open Graph and Twitter tags kept in step.
 * Next replaces `openGraph` and `twitter` wholesale when a page sets them, so a
 * page that sets only a title would otherwise share the homepage’s card.
 */
export function pageMetadata({ title, description, path, image, type = "website", publishedTime }: PageMeta): Metadata {
  const shareTitle = `${title} | ${site.shortName}`;
  const images = [image ?? DEFAULT_IMAGE];
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type,
      siteName: site.name,
      url: path,
      title: shareTitle,
      description,
      images,
      ...(publishedTime ? { publishedTime } : {}),
    },
    twitter: { card: "summary_large_image", title: shareTitle, description, images },
  };
}

/** Absolute URL for a site path. */
export const absolute = (path: string) => `${site.url}${path === "/" ? "" : path}`;

/** Parse a content date like “October 26, 2024”; undefined when it isn’t a real date. */
export function isoDate(date: string) {
  const t = Date.parse(date);
  return Number.isNaN(t) ? undefined : new Date(t).toISOString();
}

/** BreadcrumbList from Home through each crumb; the last crumb is the current page. */
export function breadcrumbs(crumbs: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [{ name: "Home", path: "/" }, ...crumbs].map((c, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: c.name,
      item: absolute(c.path),
    })),
  };
}

/** Reference to the Organization node declared in the root layout. */
export const organizationRef = { "@id": `${site.url}/#organization` };
